function piRenderAirbnbConnect(job) {
  var box = document.getElementById('pi-airbnb-connect');
  if (!box) return;
  if (!job) { box.style.display = 'none'; box.innerHTML = ''; return; }
  box.style.display = 'block';
  var st = String(job.status || '');
  var body = '';
  if (st === 'starting' || st === 'logging_in') {
    body = '<div style="font-weight:600;margin-bottom:6px">Connecting Airbnb…</div>' +
      '<div style="color:var(--tx3);font-size:12.5px">' + (job.hint || 'Please wait') + '</div>' +
      '<div style="margin-top:10px"><button class="btn sm" onclick="piCancelAirbnbConnect()">Cancel</button></div>';
  } else if (st === 'awaiting_otp') {
    body = '<div style="font-weight:600;margin-bottom:6px">Enter Airbnb verification code</div>' +
      '<div style="color:var(--tx);font-size:12.5px;margin-bottom:6px;line-height:1.45">' +
      (job.hint || 'Check the <b>host email inbox</b> (and spam). Connect requests email OTP via Try another way (typed into otp-code-input).') +
      '</div>' +
      '<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:8px">' +
      '<input id="pi-airbnb-otp" type="text" inputmode="numeric" autocomplete="one-time-code" placeholder="code from email" ' +
      'style="width:160px;padding:7px 10px;border:1px solid var(--bdr);border-radius:8px;background:var(--bg2);font-size:14px" />' +
      '<button class="btn gold" onclick="piSubmitAirbnbOtp()">Submit code</button>' +
      '<button class="btn sm" onclick="piResendAirbnbOtp(true)">Resend as email</button>' +
      '<button class="btn sm" onclick="piCancelAirbnbConnect()">Cancel</button>' +
      '</div>' +
      (job.pageSnippet ? ('<div style="font-size:11px;color:var(--tx3);line-height:1.35">Airbnb page: ' +
        String(job.pageSnippet).replace(/</g,'&lt;').slice(0,180) + '…</div>') : '') +
      (job.clickables && job.clickables.length
        ? ('<div style="font-size:10.5px;color:var(--tx3);margin-top:4px">Visible actions: ' +
           job.clickables.slice(0, 12).map(function (t) { return String(t).replace(/</g,'&lt;'); }).join(' · ') + '</div>')
        : '');
  } else if (st === 'connected') {
    body = '<div style="font-weight:600;color:var(--tx-ok,#059669)">✓ Airbnb connected</div>' +
      '<div style="color:var(--tx3);font-size:12.5px;margin-top:4px">' + (job.hint || '') + '</div>';
  } else if (st === 'error') {
    body = '<div style="font-weight:600;color:var(--tx-err,#b91c1c)">Connect failed</div>' +
      '<div style="font-size:12.5px;margin-top:4px">' + (job.error || 'Unknown error') + '</div>' +
      '<div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap">' +
      '<button class="btn sm gold" onclick="piConnectAirbnbInApp()">Try again</button>' +
      '<button class="btn sm" onclick="piConnectSessionPaste(\'airbnb\')">Paste session JSON</button>' +
      '<button class="btn sm" onclick="piCancelAirbnbConnect()">Dismiss</button></div>';
  }
  box.innerHTML = body;
  var inp = document.getElementById('pi-airbnb-otp');
  if (inp) setTimeout(function () { try { inp.focus(); } catch (e) {} }, 50);
}

