function piRenderAirbnbConnect(job) {
  var box = document.getElementById('pi-airbnb-connect');
  if (!box) return;
  if (!job) { box.style.display = 'none'; box.innerHTML = ''; window._piAirbnbConnectStatus = ''; return; }
  box.style.display = 'block';
  var st = String(job.status || '');
  // Soft-update while awaiting OTP so poll does not wipe digits the user is typing
  if (st === 'awaiting_otp' && window._piAirbnbConnectStatus === 'awaiting_otp' && document.getElementById('pi-airbnb-otp')) {
    var hintEl = document.getElementById('pi-airbnb-otp-hint');
    if (hintEl) hintEl.innerHTML = job.hint || hintEl.innerHTML;
    var snipEl = document.getElementById('pi-airbnb-otp-snip');
    if (snipEl && job.pageSnippet) snipEl.textContent = 'Airbnb page: ' + String(job.pageSnippet).slice(0,180) + '…';
    var actEl = document.getElementById('pi-airbnb-otp-actions');
    if (actEl && job.clickables && job.clickables.length) {
      actEl.textContent = 'Visible actions: ' + job.clickables.slice(0, 12).join(' · ');
    }
    return;
  }
  window._piAirbnbConnectStatus = st;
  var body = '';
  if (st === 'starting' || st === 'logging_in') {
    body = '<div style="font-weight:600;margin-bottom:6px">Connecting Airbnb…</div>' +
      '<div style="color:var(--tx3);font-size:12.5px">' + (job.hint || 'Please wait') + '</div>' +
      '<div style="margin-top:10px"><button class="btn sm" onclick="piCancelAirbnbConnect()">Cancel</button></div>';
  } else if (st === 'awaiting_otp') {
    body = '<div style="font-weight:600;margin-bottom:6px">Enter Airbnb verification code</div>' +
      '<div id="pi-airbnb-otp-hint" style="color:var(--tx);font-size:12.5px;margin-bottom:6px;line-height:1.45">' +
