      '<div id="pi-airbnb-otp-actions" style="font-size:10.5px;color:var(--tx3);margin-top:4px">' +
      (job.clickables && job.clickables.length
        ? ('Visible actions: ' + job.clickables.slice(0, 12).map(function (t) { return String(t).replace(/</g,'&lt;'); }).join(' · '))
        : '') + '</div>';
  } else if (st === 'connected') {
    body = '<div style="font-weight:600;color:var(--tx-ok,#059669)">✓ Airbnb connected</div>' +
      '<div style="color:var(--tx3);font-size:12.5px;margin-top:4px">' + (job.hint || '') + '</div>';
  } else if (st === 'error') {
    body = '<div style="font-weight:600;color:var(--tx-err,#b91c1c)">Connect failed</div>' +
      '<div style="font-size:12.5px;margin-top:4px">' + (job.error || 'Unknown error') + '</div>' +
      '<div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap">' +
      '<button class="btn sm gold" onclick="piConnectAirbnbInApp()">Try again</button>' +
      '<button class="btn sm" onclick="piCancelAirbnbConnect()">Cancel</button></div>';
  }
  box.innerHTML = body;
  var inp = document.getElementById('pi-airbnb-otp');
  if (inp && st === 'awaiting_otp') setTimeout(function () { try { inp.focus(); } catch (e) {} }, 50);
}
